L000326	\subsection{Left invariant $1$-forms}
L000327	
L000328	The left-invariant $1$-forms on $SU(2)$ are
L000329	\begin{equation}
L000330	\begin{aligned}
L000331	&\sigma_1 = \cos \psi\,\sin \theta\,{\rm d}\phi-\sin \psi\,{\rm d}\theta\,,
L000332	\\
L000333	&\sigma_2 = \sin \psi\,\sin \theta\, {\rm d}\phi+\cos \psi\,{\rm d}\theta\,,
L000334	\\
L000335	&\sigma_3={\rm d}\psi+\cos \theta \,{\rm d}\phi\,,
L000336	\end{aligned}
L000337	\end{equation}
L000338	with $\theta\in[0,\pi]$, $\phi\sim \phi+2\pi$ and $\psi\sim \psi+4\pi$.
