L000346	\begin{equation}
L000347	\label{eq:rVV}
L000348	\frac{\Omega^2}{r}\partial_V\left(\frac{\partial_Vr}{\Omega^2}\right)=-\frac{1}{2}\left(\partial_V\mathcal{B}\right)^2-\frac{1}{6}\frac{\left|\partial_V\Phi\right|^2}{1+|\Phi|^2}-\frac{1}{24}\frac{\left|\overline{\Phi}\partial_V\Phi-\Phi \overline{\partial_V \Phi}\right|^2}{1+|\Phi|^2}\,,
L000349	\end{equation}
L000350	
