L000362	\partial_UJ=r^3 {\rm Im}\left(\Phi \overline{\mathcal{D}_U \Phi}\right)\,,
L000363	\end{equation}
L000364	\begin{equation}
L000365	\label{eq:AUV}
L000366	\partial_V\mathcal{A}_U=\frac{2J\,e^{2\mathcal{B}}\Omega^2}{r^5}\,,
