L000395	\subsection{Monotonicity of the Hawking mass}
L000396	
L000397	The equations of motion imply
L000398	\begin{subequations}
L000399	\begin{equation}
L000400	\frac{8 G_5}{3\pi}\partial_V m_{\rm H} =
L000401	\Biggl[\frac{8 J^2 e^{2\mathcal{B}}}{3 r^5}
L000402	    + \frac{2 r e^{-4 \mathcal{B}}}{3} f(e^{\mathcal{B}},|\Phi|^2)\Biggr] \partial_V r
L000403	+ \frac{2 r^3}{\Omega^2} \Biggl\{(\partial_V \mathcal{B})^2 + \frac{|\partial_V \Phi|^2}{3(1+|\Phi|^2)} + \frac{\left[{\rm Im}(\bar{\Phi} \partial_V \Phi)\right]^2}{3(1+|\Phi|^2)}\Biggr\} (-\partial_U r) \,,
L000404	\end{equation}
L000405	and
L000406	\begin{equation}
L000407	\frac{8 G_5}{3\pi}\partial_U m_{\rm H} =
L000408	-\Biggl[\frac{8 J^2 e^{2\mathcal{B}}}{3 r^5}
L000409	    + \frac{2 r e^{-4 \mathcal{B}}}{3} f(e^{\mathcal{B}},|\Phi|^2)\Biggr] (-\partial_U r)
L000410	-\frac{2 r^3}{\Omega^2} \Biggl\{(\partial_U \mathcal{B})^2 + \frac{|\mathcal{D}_U \Phi|^2}{3(1+|\Phi|^2)} + \frac{\left[{\rm Im}(\bar{\Phi} \mathcal{D}_U \Phi)\right]^2}{3(1+|\Phi|^2)}\Biggr\} \partial_V r \,,
L000411	\end{equation}
L000412	with
L000413	\begin{equation}
L000414	f(x,y)=1+3x^4+4x^6y-4x^3\sqrt{1+y}\,.
L000415	\end{equation}
L000416	\end{subequations}
L000417	(We note that $f= 3e^{4\mathcal{B}} (1-r^2 \mathcal{R}/6)$ where $\mathcal{R}$ is the Ricci scalar of a homogeneously deformed $S^3$ of constant $U,V$.) We claim that $f(x,y)\geq0$ for $x>0$ and $y\geq0$. To prove this we fix $x$ and consider $\partial_y f = 2x^3 (2x^3 - 1/\sqrt{1+y})$. For $x^3 \ge 1/2$ this gives $\partial_y f \ge 0$ so, along a line of constant $x$, $f$ is minimized at $y=0$ where we have $f(x,0)=(1-x)^2 \left(1+2 x+3 x^2\right) \ge 0$. For $0<x^3<1/2$, $\partial_y f<0$ for $y<y_{\rm min}$ and $\partial_y f>0$ for $y>y_{\rm min}$ where $y_{\rm min} = 1/(4x^6)-1$. Hence, along a line of constant $x$, $f$ is minimized at $y=y_{\rm min}$ where we have $f(x,y_{\rm min})=x^4 \left(3-4 x^2\right)$ which is positive for $0<x^3<1/2$. This completes the proof. Note that $f(1,0)=0$ so $x=1$, $y=0$ is the global minimum of $f$, which corresponds to a round sphere.
L000418	
L000419	It now follows that $\partial_U m_{\rm H} \le 0$ and $\partial_V m_{\rm H} \ge 0$ if $\partial_V r \ge 0$ and $\partial_U r \le 0$. For $\Phi=0$ this is a special case of \cite{Dafermos:2005nh}.
